var step: int := 0

contains root: example::trafficlight::intersection::EastCanTurnGreen

init {
    assume(step == 0)
    inline root.init()
    assume(root.intersection.north.color == example::trafficlight::intersection::LightColor::Red)
    assume(root.intersection.east.color == example::trafficlight::intersection::LightColor::Red)
    step := 1
}

tran {
    assume(step == 1)
    inline root.main()
    assume(root.intersection.north.color == example::trafficlight::intersection::LightColor::Red)
    assume(root.intersection.east.color == example::trafficlight::intersection::LightColor::Green)
    step := 2
}

prop {
    root.prop()
}

